GimCorpus.put(402,0,[[1,2,"אבל אינו חייב כרת עד שימות וכו'. כתב הראב\"ד ז\"ל אין בזה תבלין וכי משום התראת ספק פוטרין אותו מן השמים וכל יום עומד באיסור כרת עכ\"ל:",1,0],[1,5,"לקח שפחה לעובריה או שלקח וכו' כדי שיהא הבן יליד בית. כתב הראב\"ד ז\"ל א\"א לדעת רבי חמא מחלקים בין ילדה ואח\"כ הטבילה להטבילה ואח\"כ ילדה עכ\"ל:",1,0],[1,6,"לקח עבד גדול מן העכו\"ם כו' עד יהרג מיד. כתב הראב\"ד ז\"ל ימכר מיד אין לנו עתה להרוג איש עכ\"ל:",1,0],[1,10,"כשם שמילת הבנים כו' עד אינו דוחה את שבת. כתב הראב\"ד ז\"ל לא ידעתי מהו זה ההפרש ואולי מפני שהוא מסופק אם הלכה כרבי חמא דמפליג בטבילה ולענין מידחי שבת לחומרא ולא דחי וא\"כ במקנת כסף שנמול לשמונה נמי איכא לספוקי כי האי עכ\"ל:",1,0],[2,8,"מקום שדרכן להרחיץ את הקטן כו' עד מפני שסכנה היא לו. כתב הראב\"ד ז\"ל שחממן עכו\"ם דבשלמא אחר המילה סכנה היא לו ואפילו ישראל מצי מחמם ליה אבל לפני המילה לא משכחת לה אלא שחממם עכו\"ם ואין אומר לו אלא שחממם מעצמו עכ\"ל:",1,0],[3,1,"ואבי הבן מברך ברכה אחרת וכו' ואין ראוי לעשות כן. כתב הראב\"ד ז\"ל מסתברא כמאן דאמר בית דין או מיוחד שבעם מברך. ונהגו אצלנו שהסנדקוס מברך:",1,0],[3,6,"וכן אנדרוגינוס אין מברכין על מילתו מפני שאינו זכר ודאי. כתב הראב\"ד ז\"ל אם אנדרוגינוס ספק מברך עליו מפני שהוא ספק דאורייתא ועל ספק דאורייתא מברכין חוץ מן הדמאי מפני שרוב עמי הארץ מעשרין הן עכ\"ל:",1,0]]);
